&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des joueurs - Classes avanc&#233;es (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Class Guide/Manuel des joueurs - Classes avanc&#233;es&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoMCA.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt; &lt;i&gt;Le personnage et son compagnon sont tr&#232;s dou&#233;s pour affronter l’ennemi ensemble.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Cat&#233;gorie.&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Dons.html#DONCOMBAT&quot; title=&quot;Les dons&quot;&gt;combat&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Dons.html#DONEQUIPE&quot; title=&quot;Les dons&quot;&gt;&#233;quipe&lt;/a&gt;&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Conditions.&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;Int&quot;&gt;Int&lt;/a&gt; 13, &lt;a class=&quot;pagelink&quot; href=&quot;Expertise-Du-Combat.html&quot; title=&quot;Expertise du combat&quot;&gt;Expertise du combat&lt;/a&gt;, capacit&#233; &#224; obtenir un &lt;a class=&quot;pagelink&quot; href=&quot;Compagnons-Animaux.html&quot; title=&quot;Les compagnons animaux du druide&quot;&gt;compagnon animal&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;div style=&quot;float:right; padding-left: 6px&quot;&gt;
&lt;table&gt;
&lt;tr style=&quot;vertical-align:bottom&quot;&gt;
&lt;td style=&quot;display:none; background-color: #f3efe2; border: 1px solid #4b3124; padding: 2px; text-align: left&quot;&gt;
&lt;table&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;&lt;td&gt;
&lt;b&gt;&lt;i&gt;&lt;u&gt;Ce texte a &#233;t&#233; modifi&#233; suite &#224; la FAQ suivante :&lt;/u&gt;&lt;br /&gt;&lt;br /&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Manuel-Des-Joueurs---Classes-Avanc&#233;es.html#12&quot; title=&quot;FAQ du Manuel des joueurs - Classes avanc&#233;es&quot;&gt;→&lt;/a&gt; Tenaille de meute : Tenaille de meute est-il un don de combat ?&lt;/i&gt;&lt;/b&gt;&lt;br /&gt;&lt;br /&gt;Oui, &lt;u&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tenaille-De-Meute.html&quot; title=&quot;Tenaille de meute&quot;&gt;Tenaille de meute&lt;/a&gt;&lt;/u&gt; devrait &#234;tre un don de combat. Ce changement sera refl&#233;t&#233; dans le prochain errata.
&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/td&gt;
&lt;td&gt;&lt;img style=&quot;width:50px; cursor:pointer&quot; src=&quot;/wiki/public/upload/Illustrations/Wiki/faqbase1.png&quot; title=&quot;Cliquez pour afficher/cacher une FAQ officielle relative &#224; ce texte&quot; alt=&quot;Cliquez pour afficher/cacher l&#39;information&quot; onclick=&quot;
var cible = this.parentNode.previousSibling.previousSibling;
if (cible.style.display==&#39;none&#39;) {
  $(cible).show(&#39;slide&#39;);
  $(this).fadeTo(500,0.4);
} else {
  $(cible).hide(&#39;slide&#39;);
  $(this).fadeTo(500,1);
}&quot; ONMOUSEOVER=&quot;this.src = &#39;/wiki/public/upload/Illustrations/Wiki/faqalt1.png&#39;;&quot;
ONMOUSEOUT=&quot;this.src = &#39;/wiki/public/upload/Illustrations/Wiki/faqbase1.png&#39;;&quot; /&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;&lt;b&gt;Avantage.&lt;/b&gt; Quand le personnage et son compagnon poss&#232;dent ce don, que le compagnon est adjacent au personnage ou partage sa case et que tous deux menacent le m&#234;me adversaire, on consid&#232;re que le personnage et son compagnon prennent cet adversaire en tenaille, quelle que soit leur v&#233;ritable position.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Normal.&lt;/b&gt; Le personnage doit &#234;tre plac&#233; &#224; l’oppos&#233; de son alli&#233; pour prendre un adversaire en tenaille.
